const menuIcon="<svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M4 6h16M4 12h16M4 18h16\"/></svg>",closeIcon="<svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"m5 5 14 14M5 19 19 5\"/></svg>";
const menu=document.querySelector('.menu-toggle');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Menüyü kapat':'Menüyü aç');document.querySelector('header').classList.toggle('menu-open',open);menu.innerHTML=open?closeIcon:menuIcon;});
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('header').classList.remove('menu-open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Menüyü aç');menu.innerHTML=menuIcon;}));
let listings=[],filter='all',expanded=true,searchTown='all',searchRooms='all',searchBudget=0;
const grid=document.querySelector('#listings'),more=document.querySelector('#more-listings');
function render(){if(!grid)return;let data=listings.filter(x=>(filter==='all'||(filter==='rent'?x.rent:!x.rent))&&(searchTown==='all'||x.town===searchTown)&&(searchRooms==='all'||x.rooms===searchRooms)&&(!searchBudget||x.price<=searchBudget));document.querySelector('#result-count').textContent=data.length+' gayrimenkul';grid.replaceChildren();if(!data.length){const empty=document.createElement('div');empty.className='empty-results';empty.innerHTML='<h3>Bu aramaya uygun ilan bulunamadı.</h3><p>Filtreleri değiştirin veya aradığınız evi birlikte bulalım.</p><a class="button primary" href="#iletisim">Arayışımı paylaşmak istiyorum ↗</a>';grid.append(empty);}data.slice(0,expanded?data.length:6).forEach(x=>{const a=document.createElement('article');a.className='listing';a.innerHTML=`<a class="listing-image" href="/ilan/${x.code.toLowerCase()}/"><img width="900" height="600" decoding="async" src="/${x.image}" alt="${x.town}, ${x.neighborhood} gayrimenkul fotoğrafı" loading="lazy"><span class="tag">${x.rent?'KİRALIK':'SATILIK'}</span><span class="image-arrow" aria-hidden="true">↗</span></a><div class="listing-body"><p class="listing-location">İZMİR / ${x.town.toLocaleUpperCase('tr-TR')}</p><h3>${x.displayTitle||x.title.toLocaleLowerCase('tr-TR')}</h3><p class="listing-specs">${x.neighborhood} <span>·</span> ${x.rooms} <span>·</span> ${x.area} m²</p><div class="listing-bottom"><strong>${new Intl.NumberFormat('tr-TR').format(x.price)} ₺${x.rent?'<small> / ay</small>':''}</strong><a class="listing-cta" href="/ilan/${x.code.toLowerCase()}/" aria-label="${x.title} ilanını inceleyin"><span>İlanı incele</span><svg class="action-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6 18 18 6M6 6h12v12"/></svg></a></div></div>`;grid.append(a);});more.hidden=expanded||data.length<=6;}
fetch('/listings.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{listings=data;render();if(typeof populateCalculator==='function')populateCalculator();}).catch(()=>{if(!grid)return;grid.innerHTML='<p>Portföy şu anda yüklenemedi. Güncel ilanlar için <a href="https://remax.com.tr/tr/danisman/43800/burcu-onay-tunali?tab=portfoylerim">RE/MAX profilini ziyaret edebilirsiniz.</a></p>';more.hidden=true;});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;expanded=false;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();}));more?.addEventListener('click',()=>{expanded=true;render();});
document.querySelector('#contact-form')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target),message=`Merhaba Burcu Hanım, ben ${d.get('name').trim()}.\n${d.get('interest')}.\n${d.get('message').trim()}`;window.open('https://wa.me/905442355466?text='+encodeURIComponent(message),'_blank','noopener,noreferrer');});
document.querySelector('#property-search')?.addEventListener('submit',e=>{e.preventDefault();filter=document.querySelector('#search-type').value;searchTown=document.querySelector('#search-town').value;searchRooms=document.querySelector('#search-rooms').value;searchBudget=Number(document.querySelector('#search-budget').value)||0;expanded=false;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x.dataset.filter===filter);x.setAttribute('aria-pressed',String(x.dataset.filter===filter));});document.querySelector('#reset-search').hidden=false;render();document.querySelector('#portfoy').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});
document.querySelector('#reset-search')?.addEventListener('click',()=>{document.querySelector('#property-search').reset();searchTown='all';searchRooms='all';searchBudget=0;filter='all';expanded=false;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x.dataset.filter==='all');x.setAttribute('aria-pressed',String(x.dataset.filter==='all'));});document.querySelector('#reset-search').hidden=true;render();});
document.querySelectorAll('[data-intent="sale"]').forEach(a=>a.addEventListener('click',()=>{const input=document.querySelector('#interest');if(input)input.value='Gayrimenkulümü satmak istiyorum';}));
document.querySelector('#year').textContent=new Date().getFullYear();

const params=new URLSearchParams(location.search),interest=document.querySelector('#interest');
if(interest&&params.get('hizmet'))interest.value=params.get('hizmet')==='satis'?'Gayrimenkulümü satmak istiyorum':'Kiralık ev arıyorum';
document.querySelectorAll('[data-gallery]').forEach(button=>button.addEventListener('click',()=>{const image=document.querySelector('#gallery-main');image.src=button.dataset.gallery;document.querySelectorAll('[data-gallery]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));
